import { PlaneGeometry, MeshStandardMaterial, Mesh, Group, Vector3 } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Load textures via context loader (cached)
  const colorTexture = ctx.textureLoader.load(config.assets.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.assets.depthMapUrl);

  // Create tessellated plane geometry for displacement
  const geometry = new PlaneGeometry(1, 1, 64, 64);

  // Create material with machined metal PBR properties
  const material = new MeshStandardMaterial({
    map: colorTexture,
    normalMap: depthTexture,
    normalScale: new Vector3(1.5, 1.5),
    metalness: 0.35,
    roughness: 0.65,
    clearcoat: 0.15,
    clearcoatRoughness: 0.8,
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Apply scene transforms
  if (config.sceneNodeData) {
    group.position.set(...config.sceneNodeData.position);
    group.rotation.order = 'YXZ';
    group.rotation.set(...config.sceneNodeData.rotation);
    group.scale.set(...config.sceneNodeData.scale);
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives?.length) {
    for (const prim of config.cinematicPrimitives) {
      ctx.primitives?.[prim.name]?.(group, prim.params || {});
    }
  }

  // Animation state
  const timelines = [];
  const baseY = config.sceneNodeData?.position?.[1] ?? 0;

  // Event handlers
  group.userData.handlers = {
    onMouseEnter: () => {
      timelines.forEach(t => t.kill());
      timelines.length = 0;
      const tl = gsap.to(group.position, {
        y: baseY + 0.15,
        duration: 0.5,
        ease: 'power2.out',
      });
      timelines.push(tl);
    },

    onMouseLeave: () => {
      timelines.forEach(t => t.kill());
      timelines.length = 0;
      const tl = gsap.to(group.position, {
        y: baseY,
        duration: 0.5,
        ease: 'power2.out',
      });
      timelines.push(tl);
    },

    onClick: () => {
      timelines.forEach(t => t.kill());
      timelines.length = 0;
      const tl = gsap.timeline()
        .to(mesh.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'back.out',
        })
        .to(mesh.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.12,
          ease: 'back.out',
        }, '>');
      timelines.push(tl);
    },
  };

  // Cleanup
  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    timelines.length = 0;
    geometry.dispose();
    material.dispose();
    colorTexture.dispose();
    depthTexture.dispose();
  };

  return group;
}
